import { RendererCanvas, getImgFromURL, TypeDithering, dithering4_4, ditheringFloydSteinberg, getArrayBinaryImgFromCtx, DitheringFloyd } from '../../../lib';
// import { } from '../../../'
import { setData } from '../../DB/FireBase';

export class Solution {
	public divHost: HTMLElement;
	public renderer: Renderer;
	constructor(id: string) {
		this.divHost = document.getElementById(id);

		// Center align
		this.divHost.style.display = 'flex';
		this.divHost.style.alignItems = 'center';
		const div = document.createElement('div');
		div.style.marginLeft = 'auto';
		div.style.marginRight = 'auto';
		div.style.backgroundColor = '#555';
		div.style.margin = '50px';
		div.style.background = 'rgba(0,0,0,0)';
		this.divHost.appendChild(div);

		this.renderer = new Renderer(div);
	}
	public destroy() {
		this.renderer.destroy();
		while (this.divHost.lastElementChild) {
			this.divHost.removeChild(this.divHost.lastElementChild);
		}
	}
}

export class Renderer extends RendererCanvas {
	public img: HTMLImageElement | undefined = undefined;
	public rotation = 0.0;
	public m: number[] = [0, 0];

	switch = true;

	typeDithering: TypeDithering = TypeDithering.FloydSteinberg;
	constructor(div: any) {
		super(div);

		this.ctx = this.canvas.getContext('2d', { willReadFrequently: true }) as CanvasRenderingContext2D;

		this.canvas.style.position = 'relative';
		this.canvas.style.width = '100%';
		this.canvas.style.height = '100%';

		// getImgFromURL('https://raw.githubusercontent.com/NamjuLee/data/master/img/person/HaminHaram.jpg').then( (img: HTMLImageElement) => {
		getImgFromURL('https://www.glenstone.org/wp-content/uploads/2018/07/AV_Landscape-Hero-Contour-2993-1276x800.jpg').then((img: HTMLImageElement | void) => {
			if (!img) return;
			this.img = img;
			this.img.onload = (ev) => {
				this.update(img);
			};
		});
		const divInput = document.createElement('input');
		divInput.value = 'https://raw.githubusercontent.com/NamjuLee/data/master/img/person/HaminHaram.jpg';
		divInput.addEventListener('keydown', (e: KeyboardEvent) => {
			if (e.code === 'Enter') {
				getImgFromURL(divInput.value).then((img: HTMLImageElement | void) => {
					if (!img) return;
					this.img = img;
					this.img.onload = (ev) => {
						this.update(img);
					};
				});
			}
		});
		this.divHost.appendChild(divInput);

		const divMain_01 = document.createElement('div');
		divMain_01.style.display = 'flex';
		divMain_01.style.marginTop = '15px';
		this.divHost.appendChild(divMain_01);

		const slType = getSlider(TypeDithering.FloydSteinberg, 0, 2);
		slType.slider.defaultValue = '0';
		this.divHost.appendChild(slType.div);
		slType.slider.oninput = () => {
			const value = parseInt(slType.slider.value);

			if (value === 0) {
				this.typeDithering = TypeDithering.FloydSteinberg;
				slType.text.textContent = TypeDithering.FloydSteinberg;
			} else if (value === 1) {
				this.typeDithering = TypeDithering.BayerOrderedDithering;
				slType.text.textContent = TypeDithering.BayerOrderedDithering;
			} else {
				this.typeDithering = TypeDithering.None;
				slType.text.textContent = TypeDithering.None;
			}
			this.render(this.ctx, this.typeDithering);
		};

		const divButtonImgLoad = buttonImgLoad((img: HTMLImageElement) => {
			this.img = img;
			this.canvas.width = this.img.width;
			this.canvas.height = this.img.height;
			this.render(this.ctx, this.typeDithering);
		});
		divMain_01.appendChild(divButtonImgLoad);

		const divID = document.createElement('div');
		divMain_01.appendChild(divID);
		divID.style.width = '100px';
		divID.style.background = '#fff';
		divID.style.paddingRight = '50px';
		divID.contentEditable = 'true';
		divID.textContent = 'id';

		const divLight = document.createElement('div');
		divMain_01.appendChild(divLight);
		divLight.textContent = 'Base64 to clipboard';
		divLight.style.paddingRight = '50px';
		divLight.onclick = () => {
			const base64 = this.ctx.canvas.toDataURL();
			// console.log(base64);
			this.getByAPI();

			copyContent(base64);

			setData('image', divID.textContent, { base64: base64 });
		};

		const divDownload = document.createElement('div');
		divMain_01.appendChild(divDownload);
		divDownload.textContent = 'Download';
		divDownload.style.paddingLeft = '50px';
		divDownload.style.paddingRight = '50px';
		divDownload.onclick = () => {
			const d = getArrayBinaryImgFromCtx(this.ctx);
			fileDownload(d);
		};

		this.start();
	}
	public async getByAPI() {
		// // https://openweathermap.org/api
		// const CityName = "Seoul";
		// const query = `http://api.openweathermap.org/data/2.5/weather?q=${CityName}&appid=${this.API_KEY}&units=metric`;

		const query = `http://127.0.0.1:5001/njs-lab/us-central1/ditheringString?url=https://img.mbn.co.kr/filewww/news/other/2015/12/16/060081001581.png`;

		getJSONFromURL(query).then((d) => {
			// console.log('ddddd', d)
			// this.data.push(d)
		});
	}
	public update(img: HTMLImageElement) {
		this.img = img;
		this.canvas.width = this.img.width;
		this.canvas.height = this.img.height;
		this.render(this.ctx, this.typeDithering);
	}
	public render(ctx: CanvasRenderingContext2D, typeDitheringType?: TypeDithering): void {
		if (this.img === undefined) {
			return;
		}
		ctx.clearRect(0, 0, ctx.canvas.width, ctx.canvas.height);

		if (this.img) {
			this.ctx.drawImage(this.img, 0, 0);
		}
		this.ctx.restore();

		switch (typeDitheringType) {
			case TypeDithering.FloydSteinberg:
				ditheringFloydSteinberg(ctx);
				// DitheringFloyd.make(ctx);
				break;
			case TypeDithering.BayerOrderedDithering:
				dithering4_4(ctx);
				break;
			default:
				break;
		}

		// !! can stop render after this frame.
		this.isStatic = true;
	}
}
const getSlider = (title: string, min: number, max: number) => {
	// <input type="range" min="1" max="100" value="50" class="slider" id="myRange">
	const div = document.createElement('div');
	div.style.display = 'flex';

	const slider = document.createElement('input');
	slider.type = 'range';
	slider.min = `${min}`;
	slider.max = `${max}`;

	const text = document.createElement('div');
	text.textContent = title;
	text.style.color = '#aaa';
	div.appendChild(slider);
	div.appendChild(text);
	return {
		div,
		slider,
		text,
	};
};
const buttonImgLoad = (callback: (img: HTMLImageElement) => void) => {
	const inputFile = document.createElement('input');
	inputFile.type = 'file';
	inputFile.onchange = (e) => {
		//@ts-ignore
		if (e.target.files) {
			//@ts-ignore
			let imageFile = e.target.files[0]; //here we get the image file
			var reader = new FileReader();
			reader.readAsDataURL(imageFile);
			reader.onloadend = (e) => {
				const img = new Image(); // Creates image object
				//@ts-ignore
				img.src = e.target.result; // Assigns converted image to image object
				img.onload = (ev) => {
					callback(img);
				};
			};
		}
	};
	return inputFile;
};
const fileDownload = (d: any, fileName: string = 'img.txt') => {
	const blob = new Blob(d, { type: 'text/plain' });
	const link = document.createElement('a');
	link.download = fileName;
	link.href = URL.createObjectURL(blob);
	link.click();
	URL.revokeObjectURL(link.href);
};
const copyContent = async (base64: any) => {
	try {
		await navigator.clipboard.writeText(base64);
		console.log('Content copied to clipboard');
	} catch (err) {
		console.error('Failed to copy: ', err);
	}
};

export const getJSONFromURL = async (url: string) => {
	return await await (
		await fetch(url)
	).text;
};
